command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="b414e8e3f8eb5e6c771c1f41ba4e632c143b1db4"
$candidate="108cedb5c17a1229604dc6f7a43fbc7c2eb775ab"
$branch="work/shell-provider-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider docs policy fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider docs policy validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider docs policy candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){
  $dirty|ForEach-Object{Write-Host ("UNEXPECTED_WORKTREE="+$_)}
  throw "persistent checkout is dirty before provider docs policy validation"
}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider docs policy checkout failed"}
& .\test.bat policy
if($LASTEXITCODE -ne 0){throw "provider docs policy gate failed"}
& git diff --check $main $candidate
if($LASTEXITCODE -ne 0){throw "provider docs git diff --check failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider docs policy"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider docs policy"}
Write-Host "SHELL_PROVIDER_VISUAL_DOCS_POLICY=PASS"
